import type { FC } from 'react';
import { useMemo, useRef } from 'react';
import { useSearchParams } from 'react-router-dom';
import type QRCodeStyling from 'qr-code-styling';
import ShareLayout from '@/components/share/ShareLayout';
import QrPreview from '@/components/tools/qr-generator/QrPreview';
import ExportBar from '@/components/tools/qr-generator/ExportBar';
import { decodeShareState } from '@/lib/share/encode';
import { buildQrPayload } from '@/lib/qr/payload';
import { DEFAULT_QR_STYLE, type QrStyleState } from '@/lib/qr/style';
import type { QrContentType, QrFieldsMap } from '@/lib/qr/types';

interface QrShareState {
  contentType: QrContentType;
  fields: QrFieldsMap[QrContentType];
  style: Omit<QrStyleState, 'imageDataUrl'>;
  hadLogo: boolean;
}

const QrGeneratorShare: FC = () => {
  const [searchParams] = useSearchParams();
  const qrRef = useRef<QRCodeStyling | null>(null);

  const state = useMemo(() => {
    const encoded = searchParams.get('d');
    if (!encoded) return null;
    return decodeShareState<QrShareState>(encoded);
  }, [searchParams]);

  const payload = useMemo(() => {
    if (!state) return '';
    return buildQrPayload(state.contentType, state.fields);
  }, [state]);

  if (!state || !payload) {
    return (
      <ShareLayout title="Invalid link" toolPath="/tools/qr-generator" toolName="QR Code Generator">
        <div className="max-w-md mx-auto text-center py-16">
          <h1 className="text-2xl font-display font-medium mb-3 text-accent">This link is broken</h1>
          <p className="text-muted-foreground">
            It's missing or malformed. Open the tool below to generate a fresh QR code and share link.
          </p>
        </div>
      </ShareLayout>
    );
  }

  const style: QrStyleState = { ...DEFAULT_QR_STYLE, ...state.style, imageDataUrl: null };

  return (
    <ShareLayout title="Shared QR code" toolPath="/tools/qr-generator" toolName="QR Code Generator">
      <div className="max-w-md mx-auto text-center py-8 space-y-6">
        <h1 className="sr-only">Shared QR code</h1>

        <QrPreview data={payload} style={style} qrRef={qrRef} />

        <div className="flex justify-center">
          <ExportBar qrRef={qrRef} disabled={!payload} />
        </div>

        {state.hadLogo && (
          <p className="text-xs text-muted-foreground/70">
            Note: the sender's custom logo image isn't included in shared links.
          </p>
        )}
      </div>
    </ShareLayout>
  );
};

export default QrGeneratorShare;
